const mkQuest = (over) => ({
  title: over.id, xpReward: 100, tier: 2, progress: 0, completed: false, claimed: false, ...over,
});

// Seed the store's persisted questState so the hook's initializer (QuestSystem.jsx:98-100) adopts THESE
// as the active feed. kill_type quests only enter via the claim drip-feed in normal play, so seeding is
