const byId = (result) => Object.fromEntries(result.current.quests.map((q) => [q.id, q]));

describe('B6b — a kill_type quest advances ONLY for its own mob', () => {
  beforeEach(() => {
    _resetMobKillBus();
    GameMethods.grantXP = vi.fn();
    GameMethods.spawnLootDrop = vi.fn();
  });
  afterEach(() => { cleanup(); vi.restoreAllMocks(); });

  it('killing a SPIDER advances Spider Hunter but NOT the zombie/ember/brute hunts', () => {
