    seedActive([
      mkQuest({ id: 'zombie_slayer', type: 'kill_type', mobType: 'zombie', target: 10 }),
      mkQuest({ id: 'spider_hunter', type: 'kill_type', mobType: 'spider', target: 8 }),
      mkQuest({ id: 'ember_hunter', type: 'kill_type', mobType: 'emberhusk', target: 10 }),
      mkQuest({ id: 'brute_breaker', type: 'kill_type', mobType: 'moss_brute', target: 5 }),
