// @vitest-environment jsdom
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { render, fireEvent, cleanup } from '@testing-library/react';
import { CraftingTable } from '../../src/ui/panels/CraftingTable.jsx';
import { useGameStore } from '../../src/store/useGameStore.jsx';

// B3d — THE CRAFTING GRID EATS YOUR MATERIALS.
// (18-domain review, HIGH, re-verified against live HEAD 2026-07-20.)
//
// CraftingTable places a material by REMOVING it from inventory (handleGridClick, CraftingTable.jsx:85-88)
// and escrowing it in a React-LOCAL `grid` useState (CraftingTable.jsx:22). Closing the panel unmounts the
// component (MenuSystem.jsx:122-130 renders it only while `showCrafting`), which discards that local state.
// Nothing ever gives the escrowed materials back. So a child who drops iron into the grid, changes their
// mind, and presses C to close has just permanently destroyed their iron. There is no undo and no respawn.
//
// THE INVARIANT: the 3x3 grid is ESCROW, not a sink. Whatever is still sitting in the grid when the panel
// tears down belongs to the player and must return to inventory. A crafted recipe is the ONE exception —
// doCraft clears the grid before teardown, so its consumed inputs are already gone and must NOT come back.
//
// These gates drive the REAL panel + the REAL store: they click the REAL grid cells (which run the REAL
// removeFromInventory) and then UNMOUNT (which models MenuSystem flipping showCrafting to false), asserting
// the store's inventory is made whole. No source-grep, no mock store.
//
// MUTATION-PROOF: delete/neuter the unmount-cleanup call to returnGridToInventory in CraftingTable and
// `THE BUG` goes RED again; refund everything unconditionally (ignore that doCraft cleared the grid) and
// `CRAFT SEMANTICS` goes RED.

const g = () => useGameStore.getState();
const ORIGINAL = { inventory: g().inventory, selectedBlock: g().selectedBlock };

afterEach(() => {
  cleanup();                                  // any test that did not unmount() itself
  useGameStore.setState({ ...ORIGINAL });     // restore the real starting loadout
});

// The grid cells are <div onClick> (not buttons); the grid Panel carries `.bg-well` and its 9 children are
// the cells in index order. The result/craft trigger div wraps the `.h-24` Slot. (Same structural selectors
// the existing crafting-table integration test uses.)
const gridCells = (c) => c.querySelector('.bg-well').children;
const craftTrigger = (c) => c.querySelector('.h-24').parentElement;
const place = (cells, idx) => idx.forEach((i) => fireEvent.click(cells[i]));

describe('B3d crafting-grid escrow — closing the panel must not destroy what is in the grid', () => {
  it('THE BUG: materials left in the grid on close return to inventory', () => {
    useGameStore.setState({ inventory: { blocks: { stone: 5 }, tools: {}, magic: {} }, selectedBlock: 'stone' });

    const { container, unmount } = render(<CraftingTable onClose={() => {}} />);
    place(gridCells(container), [0, 1, 2]);                 // drop 3 stone into the grid
    expect(g().inventory.blocks.stone).toBe(2);            // debited on place (5 - 3) — this is intended

    unmount();                                             // player presses C / clicks X -> panel unmounts

    expect(g().inventory.blocks.stone).toBe(5);           // <- RED before the fix: it stayed at 2 (destroyed)
  });

  it('returns EXACTLY what was in the grid across mixed materials — no more, no less', () => {
    useGameStore.setState({ inventory: { blocks: { stone: 5, wood: 5 }, tools: {}, magic: {} }, selectedBlock: 'stone' });

    const { container, unmount } = render(<CraftingTable onClose={() => {}} />);
    const cells = gridCells(container);
    place(cells, [0, 1]);                                  // 2 stone -> stone 3
    useGameStore.getState().setSelectedBlock('wood');     // switch the held material (re-renders the panel)
    place(cells, [2]);                                    // 1 wood  -> wood 4
    expect(g().inventory.blocks.stone).toBe(3);
    expect(g().inventory.blocks.wood).toBe(4);

    unmount();

    expect(g().inventory.blocks.stone).toBe(5);           // both fully restored
    expect(g().inventory.blocks.wood).toBe(5);
  });

  it('only LIVE grid cells are returned — a material clicked back out is not double-counted', () => {
    useGameStore.setState({ inventory: { blocks: { stone: 5 }, tools: {}, magic: {} }, selectedBlock: 'stone' });

    const { container, unmount } = render(<CraftingTable onClose={() => {}} />);
    const cells = gridCells(container);
    place(cells, [0, 1]);                                  // stone 5 -> 3
    fireEvent.click(cells[0]);                             // click a filled cell -> returns 1 now, cell nulled -> stone 4

    unmount();                                             // only cell 1 is still occupied

    expect(g().inventory.blocks.stone).toBe(5);           // 4 + the 1 that was still in the grid — never 6
  });

  it('CRAFT SEMANTICS: crafting then closing does NOT refund the consumed inputs', () => {
    // Leather Helmet = [['Leather','Leather','Leather'],['Leather',null,'Leather']] — survives the
    // bounding-box normalize. doCraft clears the grid, so the cleanup must find nothing to return.
    useGameStore.setState({ inventory: { blocks: { Leather: 6 }, tools: {}, magic: {} }, selectedBlock: 'Leather' });

    const { container, unmount } = render(<CraftingTable onClose={() => {}} />);
    place(gridCells(container), [0, 1, 2, 3, 5]);          // Leather 6 -> 1
    fireEvent.click(craftTrigger(container));             // craft the helmet
    expect(g().inventory.blocks['Leather Helmet']).toBe(1);
    expect(g().inventory.blocks.Leather).toBe(1);         // inputs consumed

    unmount();

    expect(g().inventory.blocks.Leather).toBe(1);         // still 1 — the consumed inputs are NOT refunded
    expect(g().inventory.blocks['Leather Helmet']).toBe(1); // and the output is not doubled
  });
});

describe('B3d — the escrow-reconciliation seam is pure and injectable', () => {
  it('returnGridToInventory tallies live cells and credits them once each', async () => {
    // Drives the extracted seam directly with an injected sink — no store, no render.
    const { returnGridToInventory } = await import('../../src/game/craftingGrid.js');
    const grid = ['iron', null, 'iron', null, 'wood', null, null, null, null];
    const credited = [];
    returnGridToInventory(grid, (item, count) => credited.push([item, count]));
    const merged = Object.fromEntries(credited);
    expect(merged.iron).toBe(2);
    expect(merged.wood).toBe(1);
    expect(credited.reduce((n, [, c]) => n + c, 0)).toBe(3);   // exactly the 3 occupied cells
  });

  it('an all-empty grid credits nothing', async () => {
    const { returnGridToInventory } = await import('../../src/game/craftingGrid.js');
    let calls = 0;
    returnGridToInventory(Array(9).fill(null), () => { calls++; });
    expect(calls).toBe(0);
  });
});

B3d-crafting-grid-eats.fix_plan:
SEAM-EXTRACTION (a pure/injectable module + one unmount-time reconciliation call), not a call-site patch. Chosen approach: RETURN THE GRID ON UNMOUNT (the task's option A). It keeps the existing "debit-on-place" UX — the mini-inventory counts decrement live as you fill the grid — and keeps craft semantics exactly (doCraft already clears the grid before teardown, so consumed inputs are never returned). The alternative (defer removal until craft) would require a reserved/available split across handleGridClick's guard at line 85 and the mini-inventory render at 193-213, a far larger blast radius.

FILE 1 (NEW) — frontend/src/game/craftingGrid.js  (pure, no React, no store import):
```
// Pure escrow reconciliation for the crafting grid. Materials placed into the 3x3 grid are debited
// from inventory at place-time (CraftingTable.handleGridClick); the grid is React-local escrow. If the
// panel unmounts with items still in it, that escrow must be credited back or it is destroyed (B3d).
// Injected `addToInventory` sink keeps this unit-testable and reusable by any future teardown path.
export function gridTally(grid) {
  const tally = new Map();
  for (const cell of grid) if (cell) tally.set(cell, (tally.get(cell) || 0) + 1);
  return tally;
}
export function returnGridToInventory(grid, addToInventory) {
  const tally = gridTally(grid);
  for (const [item, count] of tally) addToInventory(item, count);
  return tally;
}
```

