  /**
   * questMatch.js — the SINGLE authority for "does this progress event advance this quest".
   * onMobKill fires a generic 'kill' event AND a targeted 'kill_type' event for the SAME kill; a
   * generic 'kill' quest must count that kill EXACTLY ONCE (it matches the 'kill' event, NOT the
   * 'kill_type' echo). A targeted 'kill_type' quest advances only on a kill of ITS own mobType.
   */
  export function questMatchesEvent(quest, type, extra = {}) {
    if (!quest) return false;
    // targeted-hunt quests: advance only on a kill_type event for THIS mob (mobType-gated).
    if (quest.type === 'kill_type') {
      return type === 'kill_type' && quest.mobType === extra.mobType;
    }
    // every other quest — including generic 'kill' — advances only on its OWN event type.
    // B6a: a generic 'kill' quest does NOT match the 'kill_type' echo -> no double count.
    return quest.type === type;
  }

