import { CraftingTable } from '../../src/ui/panels/CraftingTable.jsx';
import { useGameStore } from '../../src/store/useGameStore.jsx';
import { RECIPES } from '../../src/data/recipes.js';
import { matchRecipe, normalizeGrid, trimGrid } from '../../src/game/crafting.js';

// B3a — THE ENTIRE SWORD TREE IS UNCRAFTABLE. (18-domain review, CRITICAL; re-derived from live code.)
//
// The 3x3 crafting grid is matched by trimming the PLAYER grid to its bounding box (normalizeGrid) and
// comparing it against the RAW recipe pattern (RECIPES.find(gridsEqual)). Every sword is a null-bordered
// middle column — e.g. Iron Sword = [[null,'iron',null],[null,'iron',null],[null,'wood',null]]. Placing
// it trims to the 3x1 column [['iron'],['iron'],['wood']], which is then compared against the padded 3x3
// pattern; gridsEqual bails on the row-length mismatch (1 !== 3). Result: Stone / Iron / Iron(Nuggets) /
// Diamond Sword can never match. The existing integration test (crafting-table.test.jsx:29-30) even
// documents the bug — it deliberately crafts a Leather Helmet "unlike the null-bordered swords".
//
