FILE 1 (NEW) frontend/src/game/crafting.js — the pure, unit-testable seam. Lift normalizeGrid + gridsEqual out of the panel and add trimGrid + matchRecipe. matchRecipe trims the player grid AND each recipe pattern before comparing:

  // crafting.js — pure recipe matcher. BOTH the player grid and each recipe pattern are trimmed to their
  // bounding box before comparison, so null-bordered patterns (the sword tree: [null,X,null] middle
  // columns) match. Trimming is idempotent for the already-tight 22 non-sword patterns.
  export function trimGrid(rows) {
    if (!rows || rows.length === 0) return null;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (let y = 0; y < rows.length; y++) {
      for (let x = 0; x < rows[y].length; x++) {
        if (rows[y][x]) {
          minX = Math.min(minX, x); maxX = Math.max(maxX, x);
          minY = Math.min(minY, y); maxY = Math.max(maxY, y);
        }
      }
    }
    if (maxX < 0) return null;                       // fully empty
    const out = [];
    for (let y = minY; y <= maxY; y++) {
      const row = [];
      for (let x = minX; x <= maxX; x++) row.push(rows[y][x] ?? null);
      out.push(row);
    }
    return out;
  }
  export function normalizeGrid(flat) {              // flat 9-slot (row-major 3x3) -> trimmed 2D, or null
    const rows = [];
    for (let y = 0; y < 3; y++) rows.push(flat.slice(y * 3, y * 3 + 3));
    return trimGrid(rows);
  }
  export function gridsEqual(g1, g2) {               // unchanged logic, lifted verbatim from the panel
    if (!g1 || !g2) return false;
    if (g1.length !== g2.length) return false;
    for (let i = 0; i < g1.length; i++) {
      if (g1[i].length !== g2[i].length) return false;
      for (let j = 0; j < g1[i].length; j++) if (g1[i][j] !== g2[i][j]) return false;
    }
    return true;
  }
  export function matchRecipe(flatGrid, recipes) {   // THE FIX: trimGrid(r.pattern) on the recipe side too
    const normalized = normalizeGrid(flatGrid);
    if (!normalized) return null;
    return recipes.find((r) => gridsEqual(normalized, trimGrid(r.pattern))) || null;
  }

