  import { BOSS_CONFIG } from './bossConfig.js';
  export function buildBossSave(state) {
    return { active: !!state.bossActive, health: state.bossHealth ?? BOSS_CONFIG.health,
             maxHealth: state.bossMaxHealth ?? BOSS_CONFIG.health, phase: state.bossPhase ?? 0,
             defeated: !!state.bossDefeated, spawned: !!state.bossSpawned };
  }
  // gameWon (or a serialized defeated flag) is authoritative: a slain dragon NEVER re-arms.
  export function rehydrateBossSave(boss, { gameWon } = {}) {
    const MAX = BOSS_CONFIG.health;
    if (gameWon || boss?.defeated)                                   // slain -> stay dead
      return { bossActive:false, bossHealth:0, bossMaxHealth:MAX, bossPhase:0, bossDefeated:true, bossSpawned:true };
    if (!boss || !boss.spawned)                                      // never met -> let the poll arm it
      return { bossActive:false, bossHealth:MAX, bossMaxHealth:MAX, bossPhase:0, bossDefeated:false, bossSpawned:false };
    const maxHealth = boss.maxHealth ?? MAX;                         // in-progress -> restore exactly
    const health = Math.max(0, Math.min(boss.health ?? maxHealth, maxHealth));
    return { bossActive: !!boss.active, bossHealth: health, bossMaxHealth: maxHealth,
             bossPhase: boss.phase ?? 0, bossDefeated:false, bossSpawned:true };
  }

