import { describe, it, expect, beforeEach } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { useGameStore } from '../../src/store/useGameStore.jsx';
import { resolvePlacement } from '../../src/world/placementEconomy';

const HERE = dirname(fileURLToPath(import.meta.url));

// B3c — FREE BLOCK PLACEMENT (18-domain review, HIGH, refuter-confirmed, re-verified on live HEAD).
// place() (Terrain.jsx:833-879) posts the voxel + plays SFX but NEVER checks or debits inventory, while
// mining grants +1 (worker 'block_broken' -> store.addToInventory(blockForId(id), 1), Terrain.jsx:587-597).
// In SURVIVAL that is the reward-theft loop: place free, mine back for +1, repeat -> unbounded diamonds.
// CREATIVE (the default sandbox, store:545) places for free BY DESIGN.
//
// THE INVARIANT: a survival placement must (a) be REFUSED when the player owns 0 of the selected block,
// and (b) debit EXACTLY 1 on success. Creative placement stays free (no debit).
//
// This DRIVES the real store accessor place() routes through (consumeForPlacement) + the pure rule —
// NOT a readFileSync+regex source-grep (the founding sin: a grep gate sat green through this exact class).
// MUTATION-PROOF: flip resolvePlacement's survival branch to { allowed: true, consume: 0 }
// (or delete the `if (!store.consumeForPlacement(type)) return;` line in place()) and these go RED.

const reset = (over = {}) => useGameStore.setState({
  gameMode: 'survival',
  inventory: { blocks: { stone: 3, diamond: 1 }, tools: {}, magic: {} },
  ...over,
});

describe('B3c free-placement — survival placement debits inventory and refuses at zero', () => {
  beforeEach(() => reset());

  it('the pure rule: survival needs stock, creative is free', () => {
    expect(resolvePlacement('survival', 0)).toEqual({ allowed: false, consume: 0 });
    expect(resolvePlacement('survival', 1)).toEqual({ allowed: true, consume: 1 });
    expect(resolvePlacement('survival', undefined)).toEqual({ allowed: false, consume: 0 });
    expect(resolvePlacement('creative', 0)).toEqual({ allowed: true, consume: 0 });
  });

  it('a survival placement debits exactly 1 of the selected block', () => {
    const s = useGameStore.getState();
    expect(s.consumeForPlacement('stone')).toBe(true);
    // 3 -> 2. Before the fix this stayed 3 forever (place() never touched inventory).
    expect(useGameStore.getState().inventory.blocks.stone).toBe(2);
  });

  it('survival placement is REFUSED at 0 stock — no block, no negative count', () => {
    reset({ inventory: { blocks: { stone: 1 }, tools: {}, magic: {} } });
    const s = useGameStore.getState();
    expect(s.consumeForPlacement('stone')).toBe(true);    // spend the last one
    expect(s.consumeForPlacement('stone')).toBe(false);   // now empty -> refuse
    expect(useGameStore.getState().inventory.blocks.stone).toBe(0);   // floored, never negative
  });

  it('a block the player has never held cannot be placed in survival (0 diamonds != free diamonds)', () => {
    reset({ inventory: { blocks: { stone: 3 }, tools: {}, magic: {} } });   // no diamond bucket at all
    expect(useGameStore.getState().consumeForPlacement('diamond')).toBe(false);
    expect(useGameStore.getState().inventory.blocks.diamond ?? 0).toBe(0);
  });

  it('CREATIVE placement stays free — the default sandbox is not nerfed', () => {
    reset({ gameMode: 'creative', inventory: { blocks: { stone: 3 }, tools: {}, magic: {} } });
    const s = useGameStore.getState();
    expect(s.consumeForPlacement('stone')).toBe(true);
    expect(s.consumeForPlacement('diamond')).toBe(true);   // free even with a 0 count
    expect(useGameStore.getState().inventory.blocks.stone).toBe(3);   // NOT debited in creative
  });

  it('the infinite-resource loop is closed: N places cost N, not 0', () => {
    reset({ inventory: { blocks: { stone: 5 }, tools: {}, magic: {} } });
    let placed = 0;
    for (let i = 0; i < 10; i++) if (useGameStore.getState().consumeForPlacement('stone')) placed++;
    expect(placed).toBe(5);                                           // ran dry after 5, not 10
    expect(useGameStore.getState().inventory.blocks.stone).toBe(0);
  });
});

// SECONDARY wiring belt (mirrors friend-foe-gates.test.jsx:172-173): the behavioral gate above proves the
// accessor is correct; this one proves place() actually ROUTES through it as a refuse-guard, so the
// call-site can't be silently dropped. NOT the primary gate — the six tests above are.
describe('B3c free-placement — place() is wired to the debit accessor', () => {
  it('Terrain.jsx place() refuses via consumeForPlacement before touching the world', () => {
    const terrain = readFileSync(resolve(HERE, '../../src/world/Terrain.jsx'), 'utf8');
    expect(terrain).toMatch(/consumeForPlacement\(/);
    expect(terrain).toMatch(/if\s*\(\s*!\s*\w+\.consumeForPlacement\([^)]*\)\s*\)\s*return/);
  });
