```
setGameTime: (timeArg) => set((state) => {
    const newTime = typeof timeArg === 'function' ? timeArg(state.gameTime) : timeArg;
    if (crossedHalfCycle(state.gameTime, newTime)) {
        // The siege ratchet advances ONLY on a genuine clock crossing into night — never on a load
        // (loadWorldData sets isDay via isDayAtUnit, no crossing) or a dev time-jump. Closes B2f.
        const enteringNight = crossedIntoNight(state.gameTime, newTime);
        return {
            gameTime: newTime,
            isDay: !state.isDay,
            ...(enteringNight ? { nightCount: state.nightCount + 1 } : {}),
        };
    }
    return { gameTime: newTime };
}),
```
