// @vitest-environment jsdom
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useBossSystem } from '../../src/world/bossSystem';
import { useGameStore } from '../../src/store/useGameStore';
import { GameMethods } from '../../src/GameMethods';

// B2h — THE BOSS KILL BLOCK RUNS ~10 SIDE EFFECTS INSIDE A setState UPDATER; ONE THROW VOIDS THE WIN.
// (18-domain review, HIGH.) A React setState updater must be PURE. bossSystem.damageBoss runs the whole
// kill (defeat UI / XP / drops / hitstop / bloom / the persisted markGameWon) inside setBossHealth(prev=>...),
// with the once-guard (bossKilledRef) committed FIRST (:88) and markGameWon() LAST (:107). A throw in any
// reward effect (e.g. grantXP touching level-up) aborts the updater with the guard already consumed, so the
// win is NEVER recorded — and every retry short-circuits on the guard. The victory is voided irrecoverably.
//
// These gates DRIVE the real hook (renderHook) + the real store — no source-grep. They force the boss active
// via the DEV forceBossSpawn fixture (present under vitest), then kill it.
//
// MUTATION-PROOF: drop the per-effect isolation in game/bossKill.js's runBossKillEffects (call the reward
// thunks un-try/catch'd) so a throw again aborts before markGameWon, and the two "THE BUG" gates go RED.

const reset = () => { useGameStore.setState({ gameWon: false, isCaptureMode: false }); };

describe('B2h boss kill-block — a reward throw must not void the win', () => {
  let savedGrantXP;
  beforeEach(() => { reset(); savedGrantXP = GameMethods.grantXP; });
  afterEach(() => { GameMethods.grantXP = savedGrantXP; });

  it('sanity: forceBossSpawn activates the boss (DEV fixture present under vitest)', () => {
    const { result } = renderHook(() => useBossSystem(0));
    expect(typeof useGameStore.getState().forceBossSpawn).toBe('function');
    act(() => { useGameStore.getState().forceBossSpawn([0, 20, 0]); });
    expect(result.current.bossActive).toBe(true);
  });

  it('a clean kill records the persisted win (characterization — green both sides)', () => {
    const { result } = renderHook(() => useBossSystem(0));
    act(() => { useGameStore.getState().forceBossSpawn([0, 20, 0]); });
    act(() => { result.current.damageBoss(1000); });
    expect(useGameStore.getState().gameWon).toBe(true);
    expect(result.current.bossDefeated).toBe(true);
  });

  it('THE BUG: a throw in a reward side effect must NOT void the persisted win', () => {
    const { result } = renderHook(() => useBossSystem(0));
    act(() => { useGameStore.getState().forceBossSpawn([0, 20, 0]); });

    // A real reward effect throwing mid-kill (grantXP touching level-up logic).
    GameMethods.grantXP = () => { throw new Error('grantXP boom'); };

    // On today's code the throw escapes the setState updater; swallow it and check the win survived.
    // (Pre-fix, React also logs a render-phase error here — that is the bug, not the test.)
    try { act(() => { result.current.damageBoss(1000); }); } catch { /* void-throw */ }

    // RED on current code: bossKilledRef was consumed before markGameWon ran, so the win was lost.
    expect(useGameStore.getState().gameWon).toBe(true);
  });

  it('THE BUG is irrecoverable: after the throw, a retry can still never record the win', () => {
    const { result } = renderHook(() => useBossSystem(0));
    act(() => { useGameStore.getState().forceBossSpawn([0, 20, 0]); });

    GameMethods.grantXP = () => { throw new Error('grantXP boom'); };
    try { act(() => { result.current.damageBoss(1000); }); } catch { /* void-throw */ }

    // Reward path is healthy again; the player keeps hitting the corpse.
    GameMethods.grantXP = () => {};
    try { act(() => { result.current.damageBoss(1000); }); } catch { /* ignore */ }

    // RED on current code: the consumed once-guard permanently blocks the kill block; gameWon stays false.
    expect(useGameStore.getState().gameWon).toBe(true);
  });
